import{_ as e,o,c as a,al as i}from"./chunks/framework.7vp1BMOE.js";const c=JSON.parse('{"title":"Community Supported Simulators","description":"","frontmatter":{},"headers":[],"relativePath":"zh/simulation/community_supported_simulators.md","filePath":"zh/simulation/community_supported_simulators.md"}'),r={name:"zh/simulation/community_supported_simulators.md"};function s(n,t,l,d,m,p){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="community-supported-simulators" tabindex="-1">Community Supported Simulators <a class="header-anchor" href="#community-supported-simulators" aria-label="Permalink to &quot;Community Supported Simulators&quot;">​</a></h1><p>This section contains information about <em>community-supported</em> simulations</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>These simulators are not maintained, tested, or supported, by the core development team. 他们可能与当前版本的 PX4 工作, 也可能不工作。</p><p>See <a href="./../dev_setup/dev_env">Toolchain Installation</a> for information about the environments and tools supported by the core development team.</p></div><p>这些工具有来自其社区的不同程度的支持 (有些得到很好的支持，有些则没有) 。 Questions about these tools should be raised on the <a href="./../contribute/support#forums-and-chat">discussion forums</a></p><table tabindex="0"><thead><tr><th>仿真器</th><th>描述</th></tr></thead><tbody><tr><td><a href="./../sim_airsim/">AirSim</a></td><td><p>A cross platform simulator that provides physically and visually realistic simulations. This simulator is resource intensive, and requires a significantly more powerful computer than the other simulators described here.</p><p><strong>Supported Vehicles:</strong> Iris (MultiRotor model and a configuration for PX4 QuadRotor in the X configuration).</p></td></tr><tr><td><a href="./../sim_flightgear/">FlightGear</a></td><td><p>A simulator that provides physically and visually realistic simulations. In particular it can simulate many weather conditions, including thunderstorms, snow, rain and hail, and can also simulate thermals and different types of atmospheric flows. <a href="./../sim_flightgear/multi_vehicle">Multi-vehicle simulation</a> is also supported.</p> <p><strong>Supported Vehicles:</strong> Plane, Autogyro, Rover</p></td></tr><tr><td><a href="./../sim_jmavsim/">JMAVSim</a></td><td><p>A simple multirotor/quad simulator. This was previously part of the PX4 development toolchain but was removed in favour of <a href="./../sim_gazebo_gz/">Gazebo</a>.</p> <p><strong>Supported Vehicles:</strong> Quad</p></td></tr><tr><td><a href="./../sim_jsbsim/">JSBSim</a></td><td><p>A simulator that provides advanced flight dynamics models. This can be used to model realistic flight dynamics based on wind tunnel data.</p> <p><strong>Supported Vehicles:</strong> Plane, Quad, Hex</p></td></tr><tr><td><a href="./../sim_pterosim/">PteroSim</a></td><td><p>Proprietary high-fidelity UAV simulation built on Unreal Engine 5 and JSBSim. Connects to PX4 SITL over the Simulator MAVLink API with lockstep synchronization.</p><p><strong>Supported Vehicles:</strong> Free tier: Multicopter. Paid tiers: Fixed-wing, VTOL, Helicopter.</p></td></tr><tr><td><a href="./../sim_rotorpy/">RotorPy</a></td><td><p>A Python-based multirotor simulation environment with aerodynamic forces and moments, actuator limits, sensor noise, wind, obstacles, and a Gymnasium interface for research workflows.</p><p><strong>Supported Vehicles:</strong> Quad</p></td></tr><tr><td><a href="./../sim_xplane/">X-Plane</a></td><td><p>A commercial flight simulator using blade element theory for flight dynamics. The PX4 integration uses the community-supported px4xplane bridge plugin.</p><p><strong>Preconfigured PX4 targets:</strong> Plane, Multicopter, VTOL. Additional X-Plane aircraft or vehicle models can be integrated when PX4 has a matching SITL-capable control path and px4xplane can map the required actuator outputs to writable X-Plane datarefs.</p></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><a href="./../sim_gazebo_gz/">Gazebo</a> and <a href="./../sim_sih/">SIH</a> are the officially supported simulators. See the <a href="./">Simulation</a> page for more information.</p></div>',6)])])}const h=e(r,[["render",s]]);export{c as __pageData,h as default};
